/* ============================================================================
 * TapMyCar  Patch  honest activation errors
 * Run:  node tapmycar-patch-activate-honest.js
 *
 * Fixes the silent fake-success bug in activate.html where activation API
 * failures (403, 500, etc.) were swallowed by the catch block and the UI
 * displayed "Tag Activated!" anyway. Now:
 *   - Activation POST response is checked: status + JSON body must succeed.
 *   - On failure: a visible red error banner shows the actual error message
 *     for ~14 seconds at the bottom of the screen.
 *   - Console.error logs the status + response body for debugging.
 *
 * Why TMC-KR7DUT failed previously: the API returned an error (likely 403
 * phone-verification-required or a missing activation session) but the UI
 * showed success. After this patch, the real error will be visible.
 *
 * Safe to re-run. No DB changes.
 * ==========================================================================*/
'use strict';
const fs = require('fs');
const path = require('path');

const STAMP = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
const BACKUP_DIR = 'backup-activate-honest-' + STAMP;
const TARGET = path.join('public', 'activate.html');
const NEW = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <link rel=\"manifest\" href=\"/manifest.json\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"TapMyCar\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0\">\n<title>Activate your tag \u2014 TapMyCar</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n<link rel=\"stylesheet\" href=\"/tmc-redesign.css\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/html5-qrcode/2.3.8/html5-qrcode.min.js\"></script>\n<style>\n.page-full{min-height:100vh;display:flex;flex-direction:column}\n.step-view{display:none;flex:1;flex-direction:column}\n.step-view.active{display:flex}\n.scan-area{width:100%;max-width:300px;height:300px;margin:0 auto;border-radius:16px;overflow:hidden;border:3px solid var(--or);position:relative}\n.scan-area video{width:100%;height:100%;object-fit:cover}\n.scan-corners{position:absolute;inset:0;pointer-events:none}\n.scan-corners::before,.scan-corners::after{content:'';position:absolute;width:40px;height:40px;border-color:var(--or);border-style:solid}\n.scan-corners::before{top:10px;left:10px;border-width:3px 0 0 3px;border-radius:8px 0 0 0}\n.scan-corners::after{top:10px;right:10px;border-width:3px 3px 0 0;border-radius:0 8px 0 0}\n.scan-line{position:absolute;left:10%;width:80%;height:2px;background:var(--or);top:50%;animation:scanMove 2s ease-in-out infinite;box-shadow:0 0 8px rgba(255,107,0,.5)}\n@keyframes scanMove{0%,100%{top:20%}50%{top:80%}}\n.result-card{background:var(--gbl);border-radius:14px;padding:16px;border:.5px solid var(--bd);margin-bottom:14px}\n.result-tag{font-size:20px;font-weight:800;color:var(--or);font-family:monospace;margin-bottom:4px}\n.result-status{font-size:11px;font-weight:600;padding:3px 10px;border-radius:99px;display:inline-block}\n.result-match{background:var(--gnl);color:var(--gn)}\n.result-new{background:var(--orl);color:var(--or)}\n.result-error{background:var(--rdl);color:var(--rd)}\n.car-option{display:flex;align-items:center;gap:12px;background:var(--gbl);border-radius:14px;padding:16px;border:1.5px solid var(--bd);cursor:pointer;margin-bottom:10px;transition:border-color .2s}\n.car-option.selected{border-color:var(--or);background:var(--orl)}\n.car-option-radio{width:22px;height:22px;border-radius:50%;border:2px solid var(--bd);display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.car-option.selected .car-option-radio{border-color:var(--or);background:var(--or)}\n.car-option.selected .car-option-radio::after{content:'';width:8px;height:8px;border-radius:50%;background:#fff}\n.consent-auto{display:flex;align-items:flex-start;gap:10px;background:var(--orl);border:1.5px solid var(--or);border-radius:14px;padding:14px;margin-bottom:14px}\n.consent-check{width:22px;height:22px;border-radius:6px;background:var(--or);display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px}\n.consent-check svg{width:12px;height:12px;stroke:#fff;fill:none;stroke-width:3;stroke-linecap:round}\n/* === PLAN PICKER & PREPAY TOGGLE === */\n.picker-label{font-size:11px;font-weight:700;color:var(--gy);text-transform:uppercase;letter-spacing:.07em;margin-bottom:10px}\n.plan-card{position:relative;background:var(--gbl);border:1.5px solid var(--bd);border-radius:14px;padding:14px 48px 14px 16px;margin-bottom:10px;cursor:pointer;transition:border-color .2s,background .2s}\n.plan-card.selected{border-color:var(--or);background:var(--orl)}\n.plan-card .plan-badge{position:absolute;top:-8px;left:14px;background:var(--bk);color:#fff;font-size:9px;font-weight:700;padding:3px 9px;border-radius:10px;letter-spacing:.04em;text-transform:uppercase}\n.plan-top{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:4px}\n.plan-name{font-size:15px;font-weight:800;color:var(--bk)}\n.plan-price{font-size:13px;font-weight:700;color:var(--or);white-space:nowrap}\n.plan-price span{font-size:10px;font-weight:500;color:var(--gy);margin-left:2px}\n.plan-sub{font-size:11px;color:var(--gy);line-height:1.5}\n.plan-radio{position:absolute;top:16px;right:14px;width:20px;height:20px;border:2px solid var(--bd);border-radius:50%;display:flex;align-items:center;justify-content:center;background:#fff}\n.plan-card.selected .plan-radio{border-color:var(--or);background:var(--or)}\n.plan-card.selected .plan-radio::after{content:'';width:8px;height:8px;border-radius:50%;background:#fff}\n.prepay-row{display:flex;align-items:center;justify-content:space-between;background:var(--gbl);border:1px solid var(--bd);border-radius:12px;padding:12px 14px;gap:12px}\n.prepay-text{flex:1}\n.prepay-title{font-size:13px;font-weight:700;color:var(--bk);margin-bottom:2px}\n.prepay-desc{font-size:11px;color:var(--gy);line-height:1.4}\n.switch{position:relative;display:inline-block;width:42px;height:24px;flex-shrink:0}\n.switch input{opacity:0;width:0;height:0}\n.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#D1D5DB;border-radius:24px;transition:.2s}\n.slider:before{position:absolute;content:\"\";height:18px;width:18px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s;box-shadow:0 1px 3px rgba(0,0,0,.15)}\n.switch input:checked + .slider{background:var(--or)}\n.switch input:checked + .slider:before{transform:translateX(18px)}\n</style>\n<!-- Favicon -->\n<link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32.png\">\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"/favicon-16.png\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<!-- SEO -->\n<meta name=\"description\" content=\"Activate your TapMyCar tag and start protecting your privacy.\">\n<meta name=\"author\" content=\"Praman Tech LLC\">\n<!-- Open Graph -->\n<meta property=\"og:title\" content=\"Activate your tag \u2014 TapMyCar\">\n<meta property=\"og:description\" content=\"Activate your TapMyCar tag and start protecting your privacy.\">\n<meta property=\"og:image\" content=\"https://tapmycar.io/og-image.png\">\n<meta property=\"og:url\" content=\"https://tapmycar.io/activate.html\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:site_name\" content=\"TapMyCar\">\n<!-- Twitter Card -->\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Activate your tag \u2014 TapMyCar\">\n<meta name=\"twitter:description\" content=\"Activate your TapMyCar tag and start protecting your privacy.\">\n<meta name=\"twitter:image\" content=\"https://tapmycar.io/og-image.png\">\n</head>\n<body>\n\n<!-- \u2550\u2550\u2550 STEP 1: SCANNER \u2550\u2550\u2550 -->\n<div class=\"step-view active\" id=\"step-scan\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"history.back()\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Activate Tag</span></div><a href=\"/dashboard.html\" aria-label=\"TapMyCar\" style=\"display:flex;align-items:center;text-decoration:none\"><img src=\"/logo.png\" alt=\"TapMyCar\" class=\"nav-logo-img\" style=\"height:36px;width:auto\"></a></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column;align-items:center\">\n    <div style=\"text-align:center;margin-bottom:20px\">\n      <div style=\"font-size:22px;font-weight:800;color:var(--bk);margin-bottom:4px\">Scan your tag</div>\n      <div style=\"font-size:13px;color:var(--gy);line-height:1.5\">Point your camera at the QR code on your<br>printed eTag or physical sticker</div>\n    </div>\n    <div class=\"scan-area\">\n      <div id=\"scanner\"></div>\n      <div class=\"scan-corners\"></div>\n      <div class=\"scan-line\"></div>\n    </div>\n    <div style=\"margin-top:16px;text-align:center\">\n      <div style=\"font-size:11px;color:var(--gy);margin-bottom:12px\">Make sure the QR code is well-lit and centered</div>\n      <button class=\"btn-o\" style=\"font-size:12px;padding:10px 24px;width:auto\" onclick=\"enterManually()\">Enter tag ID manually</button>\n    </div>\n    <!-- Manual entry (hidden) -->\n    <div id=\"manual-entry\" style=\"display:none;width:100%;margin-top:14px\">\n      <div class=\"field\">\n        <label>Tag ID</label>\n        <input type=\"text\" id=\"manual-token\" placeholder=\"e.g. TMC-XXXXXX\" oninput=\"this.value=this.value.toUpperCase()\">\n      </div>\n      <button class=\"btn\" onclick=\"processManualToken()\">Verify Tag \u2192</button>\n    </div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP 2: SCAN RESULT \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-result\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"showStep('scan')\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Scan Result</span></div></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column\">\n    <div class=\"result-card\">\n      <div class=\"result-tag\" id=\"r-token\">TMC-XXXXXX</div>\n      <div class=\"result-status\" id=\"r-status\">Checking...</div>\n      <div style=\"font-size:11px;color:var(--gy);margin-top:6px\" id=\"r-message\"></div>\n    </div>\n    <div id=\"r-action\"></div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP 3: SAME CAR OR DIFFERENT \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-car-choice\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"showStep('result')\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Your vehicle</span></div></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column\">\n    <div style=\"font-size:18px;font-weight:800;color:var(--bk);margin-bottom:4px\">Is this for the same car?</div>\n    <div style=\"font-size:13px;color:var(--gy);margin-bottom:20px\">We have your previous vehicle details on file.</div>\n    <div id=\"prev-car-info\" style=\"background:var(--gbl);border-radius:12px;padding:14px;border:.5px solid var(--bd);margin-bottom:16px\">\n      <div style=\"font-size:11px;color:var(--gy);margin-bottom:4px\">Previous vehicle</div>\n      <div style=\"font-size:14px;font-weight:700;color:var(--bk)\" id=\"prev-car-label\">Loading...</div>\n      <div style=\"font-size:11px;color:var(--gy)\" id=\"prev-car-plate\">\u2014</div>\n    </div>\n    <div class=\"car-option selected\" id=\"opt-same\" onclick=\"selectCarOption('same')\">\n      <div class=\"car-option-radio\"></div>\n      <div><div style=\"font-size:14px;font-weight:700;color:var(--bk)\">Same car</div><div style=\"font-size:11px;color:var(--gy)\">Copy all details from previous tag</div></div>\n    </div>\n    <div class=\"car-option\" id=\"opt-diff\" onclick=\"selectCarOption('diff')\">\n      <div class=\"car-option-radio\"></div>\n      <div><div style=\"font-size:14px;font-weight:700;color:var(--bk)\">Different car</div><div style=\"font-size:11px;color:var(--gy)\">Enter new vehicle details</div></div>\n    </div>\n    <div style=\"margin-top:auto\"><button class=\"btn\" onclick=\"proceedFromCarChoice()\">Continue \u2192</button></div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP 4: VEHICLE DETAILS \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-vehicle\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"goBackFromVehicle()\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Vehicle details</span></div></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column;gap:14px\">\n    <div style=\"font-size:13px;color:var(--gy)\">Enter your vehicle details</div>\n    <div class=\"field\"><label>License plate <span style=\"color:var(--rd)\">*</span></label><input type=\"text\" id=\"v-plate\" placeholder=\"ABC 1234\" oninput=\"this.value=this.value.toUpperCase()\"></div>\n    <div class=\"field\"><label>Car make</label><input type=\"text\" id=\"v-make\" placeholder=\"Honda, Toyota, Ford...\"></div>\n    <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n      <div class=\"field\" style=\"margin-bottom:0\"><label>Model</label><input type=\"text\" id=\"v-model\" placeholder=\"Civic, Camry...\"></div>\n      <div class=\"field\" style=\"margin-bottom:0\"><label>Year</label><input type=\"number\" id=\"v-year\" placeholder=\"2024\" min=\"1990\" max=\"2030\"></div>\n    </div>\n    <div class=\"field\"><label>Color</label><input type=\"text\" id=\"v-color\" placeholder=\"Silver, Black, White...\"></div>\n    <div style=\"margin-top:auto\"><button class=\"btn\" onclick=\"proceedToPayment()\">Continue \u2192</button></div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 TMC_PATCH7_ACTIVATE_SMS \u2014 STEP: PHONE VERIFY \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-phone-verify\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"showStep('vehicle')\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Verify your phone</span></div></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column;gap:14px\">\n    <div style=\"font-size:18px;font-weight:800;color:var(--bk);margin-bottom:0\">Verify your phone</div>\n    <div style=\"font-size:13px;color:var(--gy);line-height:1.5\">For your security, we'll text a 6-digit code to <span id=\"pv-masked-phone\" style=\"font-weight:700;color:var(--bk)\">your phone</span>. Enter it below to activate this tag.</div>\n\n    <div id=\"pv-send-section\" style=\"display:flex;flex-direction:column;gap:12px;margin-top:8px\">\n      <button class=\"btn\" id=\"pv-send-btn\" onclick=\"pvSendCode()\">Send code via SMS</button>\n      <div style=\"font-size:11px;color:var(--gy);text-align:center\">Wrong number? <a href=\"/settings.html\" style=\"color:var(--or);font-weight:600\">Update in Settings</a></div>\n    </div>\n\n    <div id=\"pv-code-section\" style=\"display:none;flex-direction:column;gap:12px\">\n      <div class=\"field\">\n        <label>6-digit code</label>\n        <input type=\"text\" id=\"pv-code-input\" placeholder=\"123456\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"6\" autocomplete=\"one-time-code\" style=\"font-size:24px;letter-spacing:8px;text-align:center;font-family:Menlo,monospace\">\n      </div>\n      <button class=\"btn\" id=\"pv-verify-btn\" onclick=\"pvVerifyCode()\">Verify and continue</button>\n      <button class=\"btn-o\" id=\"pv-resend-btn\" onclick=\"pvResendCode()\" disabled style=\"opacity:.6\">Resend code (60s)</button>\n      <div id=\"pv-error\" style=\"font-size:12px;color:var(--rd);text-align:center;display:none\"></div>\n    </div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP 5: PAYMENT \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-payment\">\n  <div class=\"nav\"><div class=\"bk\" onclick=\"showStep('vehicle')\"><div class=\"bkb\"><svg viewBox=\"0 0 24 24\"><polyline points=\"15 18 9 12 15 6\"/></svg></div><span class=\"bk-label\">Activate tag</span></div></div>\n  <div class=\"chev\"></div>\n  <div style=\"flex:1;padding:20px;display:flex;flex-direction:column;gap:14px;overflow-y:auto\">\n\n    <div>\n      <div class=\"picker-label\">Choose your plan</div>\n      <div class=\"plan-card selected\" id=\"plan-standard\" onclick=\"selectPlan('standard')\">\n        <div class=\"plan-top\">\n          <div class=\"plan-name\">Standard</div>\n          <div class=\"plan-price\">$9.99<span>/yr</span></div>\n        </div>\n        <div class=\"plan-sub\">1 vehicle \u00b7 10 masked calls/month \u00b7 SMS alert on every scan</div>\n        <div class=\"plan-radio\"></div>\n      </div>\n      <div class=\"plan-card\" id=\"plan-premium\" onclick=\"selectPlan('premium')\" style=\"margin-top:16px\">\n        <div class=\"plan-badge\">Best for families</div>\n        <div class=\"plan-top\">\n          <div class=\"plan-name\">Premium</div>\n          <div class=\"plan-price\">$19.99<span>/yr</span></div>\n        </div>\n        <div class=\"plan-sub\">3 vehicles \u00b7 Unlimited calls \u00b7 Scan map \u00b7 Emergency contact \u00b7 3 family gift codes</div>\n        <div class=\"plan-radio\"></div>\n      </div>\n    </div>\n\n    <div class=\"prepay-row\">\n      <div class=\"prepay-text\">\n        <div class=\"prepay-title\">Pay everything today?</div>\n        <div class=\"prepay-desc\" id=\"prepay-desc\">Off: Just $1 today. Sticker + annual billed later.</div>\n      </div>\n      <label class=\"switch\">\n        <input type=\"checkbox\" id=\"prepay-toggle\" onchange=\"updatePaymentUI()\">\n        <span class=\"slider\"></span>\n      </label>\n    </div>\n\n    <div class=\"card\">\n      <div style=\"font-size:11px;font-weight:700;color:var(--gy);text-transform:uppercase;letter-spacing:.07em;margin-bottom:12px\">Order summary</div>\n      <div id=\"summary-lines\"></div>\n    </div>\n\n    <div class=\"consent-auto\">\n      <div class=\"consent-check\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div>\n        <div style=\"font-size:13px;font-weight:700;color:#9A3800;margin-bottom:4px\" id=\"consent-title\">Auto-upgrade included</div>\n        <div style=\"font-size:11px;color:#78350F;line-height:1.5\" id=\"consent-desc\">After 30 days, your plan upgrades to Standard ($9.99) and we ship a physical NFC + QR sticker to your address.</div>\n        <!-- TMC_PATCH31_REFUND: accurate refund policy -->\n<div style=\"background:var(--gnl);border-radius:8px;padding:6px 10px;margin-top:8px\"><div style=\"font-size:10px;color:#15803D;font-weight:600\">Cancel anytime before day 30 to stop the $9.99 annual charge. The $1 activation fee is non-refundable.</div></div>\n<!-- TMC_PATCH34_AUTOMATIC_TAX: tax notice -->\n<div style=\"font-size:10px;color:#9CA3AF;margin-top:6px;text-align:center\">Sales tax calculated at checkout</div>\n      </div>\n    </div>\n\n    <div class=\"field\"><label>Shipping address <span style=\"color:var(--gy);font-weight:400\">(for physical sticker on day 30)</span></label><input type=\"text\" id=\"p-address\" placeholder=\"123 Main St, New Britain CT 06051\" autocomplete=\"street-address\"></div>\n\n    <div style=\"margin-top:auto\">\n      <button class=\"btn\" id=\"pay-btn\" onclick=\"processPayment()\">Pay $1 \u2014 Activate Tag</button>\n    </div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP 6: SUCCESS \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-success\">\n  <div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 24px;text-align:center;gap:16px\">\n    <div style=\"width:80px;height:80px;border-radius:50%;background:var(--gnl);border:3px solid var(--gn);display:flex;align-items:center;justify-content:center\">\n      <svg width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--gn)\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n    </div>\n    <div style=\"font-size:26px;font-weight:800;color:var(--bk)\" id=\"success-title\">Tag Activated!</div>\n    <div style=\"font-size:14px;color:var(--gy);line-height:1.6;max-width:280px\" id=\"success-message\">Your tag is now live. Place it on your vehicle and strangers can reach you privately anytime.</div>\n    <a href=\"/dashboard.html\" class=\"btn\" style=\"width:100%;max-width:320px;text-decoration:none;display:block;text-align:center;padding:14px 0;margin-top:8px\">Go to my dashboard</a>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550 STEP: ERROR \u2550\u2550\u2550 -->\n<div class=\"step-view\" id=\"step-error\">\n  <div style=\"flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 24px;text-align:center;gap:16px;background:var(--rd)\">\n    <div style=\"width:80px;height:80px;border-radius:50%;background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center\">\n      <svg width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linecap=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg>\n    </div>\n    <div style=\"font-size:26px;font-weight:800;color:#fff\" id=\"error-title\">Invalid Tag</div>\n    <div style=\"font-size:14px;color:rgba(255,255,255,.75);max-width:280px;line-height:1.6\" id=\"error-message\">This tag is not registered in the TapMyCar system.</div>\n    <button class=\"btn\" style=\"background:#fff;color:var(--rd);width:100%;max-width:320px\" onclick=\"showStep('scan');startScanner()\">Try again</button>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"><div class=\"toast-ic\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><span id=\"toast-msg\"></span></div>\n\n<script src=\"/app.js\"></script>\n<script>\nrequireAuth();\nconst s = getSession();\nlet scanner = null;\nlet scannedToken = '';\nlet scannedTag = null;\nlet existingTag = null; // user's current active/claimed tag\nlet carChoice = 'same';\nlet vehicleData = {};\nlet isPhysicalUpgrade = false;\n\n// Load user's existing tag data\n// TMC_PATCH33_GUARD_PAGELOAD: also redirect already-activated paid users away from this page.\nasync function loadExistingTag() {\n  try {\n    const res = await fetch('/api/get-dashboard?user_id=' + s.token);\n    const data = await res.json();\n    if (data.tags && data.tags.length > 0) {\n      existingTag = data.tags.find(t => t.status === 'active' || t.status === 'claimed') || data.tags[0];\n    }\n    /* TMC_PATCH33_GUARD_PAGELOAD: paid user with an active tag should NOT be activating anything */\n    var _userPlan = (data && data.user && data.user.plan) ? String(data.user.plan).toLowerCase() : 'etag';\n    var _activeTag = (data.tags || []).find(function(t) { return t.status === 'active'; });\n    var _isPaidPlan = (_userPlan === 'standard' || _userPlan === 'premium' || _userPlan === 'business');\n    if (_isPaidPlan && _activeTag && !window.location.search) {\n      // No ?token= in URL means user typed /activate.html directly.\n      // Show a one-second redirect notice and go to dashboard.\n      try {\n        var _msg = document.createElement('div');\n        _msg.style.cssText = 'position:fixed;inset:0;background:#fff;z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;text-align:center;font-family:Inter,system-ui,sans-serif';\n        _msg.innerHTML = '<div style=\"font-size:38px;margin-bottom:14px\">\u2705</div>' +\n          '<div style=\"font-size:18px;font-weight:800;color:#111;margin-bottom:6px\">You\\'re already activated</div>' +\n          '<div style=\"font-size:13px;color:#6B7280;margin-bottom:18px;max-width:300px\">Your ' + (_userPlan.charAt(0).toUpperCase() + _userPlan.slice(1)) + ' tag is active. Taking you to your dashboard\u2026</div>';\n        document.body.appendChild(_msg);\n      } catch(e) {}\n      setTimeout(function() { window.location.replace('/dashboard.html'); }, 1200);\n    }\n  } catch(e) { console.error(e); }\n}\nloadExistingTag();\n\n// Start QR scanner\nfunction startScanner() {\n  if (scanner) { scanner.clear(); }\n  scanner = new Html5Qrcode(\"scanner\");\n  scanner.start(\n    { facingMode: \"environment\" },\n    { fps: 10, qrbox: { width: 250, height: 250 } },\n    (text) => { onScanSuccess(text); },\n    () => {}\n  ).catch(err => {\n    console.error('Scanner error:', err);\n    showToast('Camera access needed \u2014 check permissions');\n  });\n}\n\nfunction stopScanner() {\n  if (scanner) {\n    scanner.stop().catch(() => {});\n  }\n}\n\n// Start scanner on page load\nsetTimeout(startScanner, 500);\n\nfunction enterManually() {\n  document.getElementById('manual-entry').style.display = 'block';\n}\n\nfunction processManualToken() {\n  const token = document.getElementById('manual-token').value.trim().toUpperCase();\n  if (!token) { showToast('Enter a tag ID'); return; }\n  // Clean token \u2014 remove TMC prefix and dots if user types TMC.XXXXX\n  let cleanToken = token.replace(/^HTTPS?:\\/\\/TAPMYCAR\\.IO\\/TAG\\//i, '');\n  if (!/^TMC-[A-Z0-9]+$/.test(cleanToken)) {\n    showToast('Invalid format. Tag ID must be like TMC-XXXXXX');\n    return;\n  }\n  processToken(cleanToken);\n}\n\nfunction onScanSuccess(decodedText) {\n  stopScanner();\n  // Extract token from URL like https://tapmycar.io/tag/TMCGKFJXM\n  let token = decodedText;\n  if (decodedText.includes('/tag/')) {\n    token = decodedText.split('/tag/')[1].split('?')[0].split('#')[0];\n  }\n  token = token.toUpperCase().trim();\n  processToken(token);\n}\n\nasync function processToken(token) {\n  scannedToken = token;\n  showStep('result');\n  document.getElementById('r-token').textContent = 'TMC-' + token.replace(/^TMC[-.]?/,'');\n  document.getElementById('r-status').textContent = 'Verifying...';\n  document.getElementById('r-status').className = 'result-status';\n  document.getElementById('r-message').textContent = 'Checking database...';\n  document.getElementById('r-action').innerHTML = '';\n\n  try {\n    const res = await fetch('/api/get-tag?token=' + token);\n    const data = await res.json();\n\n    if (!data.tag) {\n      // TAG NOT FOUND \u2014 fake or invalid\n      document.getElementById('r-status').textContent = 'Not found';\n      document.getElementById('r-status').className = 'result-status result-error';\n      document.getElementById('r-message').textContent = 'This tag is not registered in the TapMyCar system.';\n      document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"background:var(--rd);margin-top:14px\" onclick=\"showStep(\\'scan\\');startScanner()\">Scan a different tag</button>';\n      return;\n    }\n\n    scannedTag = data.tag;\n\n    if (scannedTag.status === 'active') {\n      // Already active\n      if (scannedTag.owner_id === s.token) {\n        document.getElementById('r-status').textContent = 'Already active';\n        document.getElementById('r-status').className = 'result-status result-match';\n        document.getElementById('r-message').textContent = 'This tag is already active on your account.';\n        document.getElementById('r-action').innerHTML = '<a href=\"/dashboard.html\" class=\"btn\" style=\"text-decoration:none;display:block;text-align:center;margin-top:14px\">Go to Dashboard</a>';\n      } else {\n        document.getElementById('r-status').textContent = 'Belongs to another user';\n        document.getElementById('r-status').className = 'result-status result-error';\n        document.getElementById('r-message').textContent = 'This tag is already registered to a different account.';\n        document.getElementById('r-action').innerHTML = '<button class=\"btn-o\" style=\"margin-top:14px\" onclick=\"showStep(\\'scan\\');startScanner()\">Scan a different tag</button>';\n      }\n      return;\n    }\n\n    /* TMC_PATCH33_GUARD_PROCESS_TOKEN: if this token already belongs to the current user (any status),\n       don't let them re-activate it \u2014 send them to dashboard. */\n    if (scannedTag.owner_id === s.token) {\n      document.getElementById('r-status').textContent = 'This is your tag';\n      document.getElementById('r-status').className = 'result-status result-match';\n      document.getElementById('r-message').textContent = 'You already own this tag. Go to your dashboard to manage it.';\n      document.getElementById('r-action').innerHTML = '<a href=\"/dashboard.html\" class=\"btn\" style=\"text-decoration:none;display:block;text-align:center;margin-top:14px\">Go to Dashboard</a>';\n      return;\n    }\n\n    if (scannedTag.status === 'disabled') {\n      document.getElementById('r-status').textContent = 'Disabled';\n      document.getElementById('r-status').className = 'result-status result-error';\n      document.getElementById('r-message').textContent = 'This tag has been disabled.';\n      return;\n    }\n\n    // TAG IS UNCLAIMED or CLAIMED\n    // Check if this tag belongs to current user (claimed eTag)\n    if (scannedTag.owner_id === s.token) {\n      // User scanning their own assigned eTag to activate\n      document.getElementById('r-status').textContent = 'Your tag \u2014 ready to activate';\n      document.getElementById('r-status').className = 'result-status result-match';\n      document.getElementById('r-message').textContent = 'This eTag is assigned to your account. Let\\'s activate it!';\n      isPhysicalUpgrade = false;\n      document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"margin-top:14px\" onclick=\"proceedFromResult()\">Activate this tag \u2192</button>';\n      return;\n    }\n\n    // Unclaimed tag + user has existing tag \u2014 this is a physical sticker upgrade\n    if (existingTag && scannedTag.status === 'unclaimed') {\n      document.getElementById('r-status').textContent = 'New tag detected';\n      document.getElementById('r-status').className = 'result-status result-new';\n      isPhysicalUpgrade = true;\n\n      // Check if user is on Standard (paid) \u2014 if so, no payment needed\n      const userRes = await fetch('/api/get-dashboard?user_id=' + s.token);\n      const userData = await userRes.json();\n      const userPlan = userData.user ? userData.user.plan : 'etag';\n\n      if (userPlan === 'standard' || userPlan === 'premium' || userPlan === 'business') {\n        document.getElementById('r-message').textContent = 'This is a new physical sticker. Add it to your account \u2014 your old eTag will be deactivated.';\n        document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"margin-top:14px\" onclick=\"proceedFromResult()\">Add this tag to my account \u2192</button>';\n      } else {\n        document.getElementById('r-message').textContent = 'New unclaimed tag detected. Activate it on your account.';\n        document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"margin-top:14px\" onclick=\"proceedFromResult()\">Activate this tag \u2192</button>';\n      }\n      return;\n    }\n\n    // Completely unclaimed, no existing tag \u2014 new activation\n    isPhysicalUpgrade = false;\n    /* TMC_PATCH35C1_GIFT_CLAIM: gift tag detection */\n    if (scannedTag && scannedTag.is_gift === true) {\n      const gMonths = Number(scannedTag.gift_months) > 0 ? Number(scannedTag.gift_months) : 1;\n      const gPlanRaw = scannedTag.gift_plan || 'standard';\n      const gPlan = gPlanRaw.charAt(0).toUpperCase() + gPlanRaw.slice(1);\n      document.getElementById('r-status').textContent = 'Gift tag';\n      document.getElementById('r-status').className = 'result-status result-new';\n      document.getElementById('r-message').innerHTML =\n        '<div style=\"background:linear-gradient(135deg,#FFF3EC,#FFE4D4);border:1px solid #FFB98A;border-radius:14px;padding:16px;margin:6px 0\">' +\n        '<div style=\"font-size:26px;margin-bottom:6px\">\\uD83C\\uDF81</div>' +\n        '<div style=\"font-weight:800;font-size:15px;color:#C2410C;margin-bottom:4px\">You received a free TapMyCar sticker!</div>' +\n        '<div style=\"font-size:13px;color:#9A3412;line-height:1.5\">Free ' + gMonths + '-month trial of the <strong>' + gPlan + '</strong> plan included. No payment needed \\u2014 just verify your phone and you are set.</div>' +\n        '</div>';\n      document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"margin-top:14px\" onclick=\"proceedFromResult()\">Claim my free sticker \\u2192</button>';\n      return;\n    }\n    document.getElementById('r-status').textContent = 'Ready to activate';\n    document.getElementById('r-status').className = 'result-status result-new';\n    document.getElementById('r-message').textContent = 'This tag is available. Activate it now!';\n    document.getElementById('r-action').innerHTML = '<button class=\"btn\" style=\"margin-top:14px\" onclick=\"proceedFromResult()\">Activate this tag \u2192</button>';\n\n  } catch(e) {\n    console.error(e);\n    document.getElementById('r-status').textContent = 'Error';\n    document.getElementById('r-status').className = 'result-status result-error';\n    document.getElementById('r-message').textContent = 'Could not verify tag. Check your connection.';\n    document.getElementById('r-action').innerHTML = '<button class=\"btn-o\" style=\"margin-top:14px\" onclick=\"showStep(\\'scan\\');startScanner()\">Try again</button>';\n  }\n}\n\nfunction proceedFromResult() {\n  // If physical upgrade and user has existing vehicle details \u2014 ask same/diff car\n  if (isPhysicalUpgrade && existingTag && existingTag.license_plate) {\n    const label = [existingTag.car_year, existingTag.car_make, existingTag.car_model].filter(Boolean).join(' ') || 'My Vehicle';\n    document.getElementById('prev-car-label').textContent = label;\n    document.getElementById('prev-car-plate').textContent = existingTag.license_plate || '\u2014';\n    showStep('car-choice');\n  } else {\n    // Go straight to vehicle details\n    showStep('vehicle');\n  }\n}\n\nfunction selectCarOption(choice) {\n  carChoice = choice;\n  document.getElementById('opt-same').classList.toggle('selected', choice === 'same');\n  document.getElementById('opt-diff').classList.toggle('selected', choice === 'diff');\n}\n\nfunction proceedFromCarChoice() {\n  if (carChoice === 'same') {\n    // Copy existing vehicle details\n    vehicleData = {\n      license_plate: existingTag.license_plate,\n      car_make: existingTag.car_make,\n      car_model: existingTag.car_model,\n      car_year: existingTag.car_year,\n      car_color: existingTag.car_color\n    };\n\n    // TMC_PATCH7_ACTIVATE_SMS: route through phone-verify step\n    flowAfterVehicle();\n  } else {\n    showStep('vehicle');\n  }\n}\n\nfunction goBackFromVehicle() {\n  if (isPhysicalUpgrade && existingTag && existingTag.license_plate) {\n    showStep('car-choice');\n  } else {\n    showStep('result');\n  }\n}\n\nfunction proceedToPayment() {\n  const plate = document.getElementById('v-plate').value.trim();\n  if (!plate) { showToast('License plate is required'); return; }\n\n  vehicleData = {\n    license_plate: plate.toUpperCase(),\n    car_make: document.getElementById('v-make').value.trim(),\n    car_model: document.getElementById('v-model').value.trim(),\n    car_year: document.getElementById('v-year').value.trim(),\n    car_color: document.getElementById('v-color').value.trim()\n  };\n\n  // TMC_PATCH7_ACTIVATE_SMS: route through phone-verify step (every activation needs fresh SMS)\n  flowAfterVehicle();\n}\n\nasync function activatePhysicalSticker(activationSessionId) {\n  /* TMC_PATCH33_GUARD_SAME_TOKEN: refuse if scanned token IS the existing tag (would deactivate-\n     then-fail-to-reactivate the same row). */\n  if (existingTag && existingTag.token && scannedToken &&\n      String(existingTag.token).toUpperCase() === String(scannedToken).toUpperCase()) {\n    console.warn('Patch33: refusing physical-upgrade on same token');\n    document.getElementById('success-title').textContent = 'Already your tag';\n    document.getElementById('success-message').textContent = 'This is the same tag you already own. No changes made. Open your dashboard to manage it.';\n    showStep('success');\n    return;\n  }\n\n  // Deactivate old eTag\n  if (existingTag) {\n    try {\n      await fetch('/api/get-tag', {\n        method: 'POST',\n        headers: {'Content-Type':'application/json'},\n        body: JSON.stringify({\n          token: existingTag.token,\n          user_id: s.token,\n          status_override: 'inactive'\n        })\n      });\n    } catch(e) { console.error('Failed to deactivate old tag:', e); }\n  }\n\n  // TMC_ACTIVATE_HONEST: actually check the API response. No more fake success.\n  let _activateOk = false;\n  try {\n    const _res = await fetch('/api/get-tag', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        token: scannedToken,\n        user_id: s.token,\n        activation_session_id: activationSessionId,\n        license_plate: vehicleData.license_plate,\n        car_make: vehicleData.car_make,\n        car_model: vehicleData.car_model,\n        car_year: vehicleData.car_year,\n        car_color: vehicleData.car_color\n      })\n    });\n    let _data = {};\n    try { _data = await _res.json(); } catch (_) {}\n    if (_res.ok && _data && _data.tag) {\n      _activateOk = true;\n    } else {\n      console.error('Activate physical sticker failed:', _res.status, _data);\n      tmcShowActivationError(_data && _data.error ? _data.error : ('Activation failed (status ' + _res.status + '). Please try again or contact support.'));\n      return;\n    }\n  } catch(e) {\n    console.error('Failed to activate new tag (network):', e);\n    tmcShowActivationError('Network error  could not reach TapMyCar. Check your connection and try again.');\n    return;\n  }\n  if (!_activateOk) return;\n\n  document.getElementById('success-title').textContent = 'New Tag Activated!';\n  document.getElementById('success-message').textContent = 'Your physical sticker is now active. Your old eTag has been deactivated. Place the sticker on your vehicle.';\n  showStep('success');\n}\n\nasync function processPayment() {\n  const btn = document.getElementById('pay-btn');\n  btn.textContent = 'Processing...';\n  btn.disabled = true;\n\n  const address = document.getElementById('p-address').value.trim();\n\n  // First save vehicle details\n  try {\n    await fetch('/api/get-tag', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        token: scannedToken,\n        user_id: s.token,\n        license_plate: vehicleData.license_plate,\n        car_make: vehicleData.car_make,\n        car_model: vehicleData.car_model,\n        car_year: vehicleData.car_year,\n        car_color: vehicleData.car_color\n      })\n    });\n  } catch(e) { console.error(e); }\n\n  // Create Stripe checkout\n  try {\n    const res = await fetch('/api/create-checkout', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        user_id: s.token,\n        flow: 'activate',\n        plan: selectedPlan,\n        prepay: prepayEnabled,\n        referral_discount: 0,\n        activation_session_id: pvActivationSessionId || (function(){ try { return localStorage.getItem('tmc_pending_activation_session'); } catch(e) { return null; } })(),\n        token: scannedToken\n      })\n    });\n    const data = await res.json();\n    if (data.url) {\n      window.location.href = data.url;\n    } else {\n      showToast(data.error || 'Payment failed');\n      btn.disabled = false;\n      updatePaymentUI();\n    }\n  } catch(e) {\n    showToast('Network error');\n    btn.disabled = false;\n    updatePaymentUI();\n  }\n}\n\n// === PLAN PICKER & PREPAY STATE ===\nvar selectedPlan = 'standard';\nvar prepayEnabled = false;\n\nfunction selectPlan(plan) {\n  selectedPlan = plan;\n  var std = document.getElementById('plan-standard');\n  var prm = document.getElementById('plan-premium');\n  if (std) std.classList.toggle('selected', plan === 'standard');\n  if (prm) prm.classList.toggle('selected', plan === 'premium');\n  updatePaymentUI();\n}\n\nfunction updatePaymentUI() {\n  var toggle = document.getElementById('prepay-toggle');\n  prepayEnabled = toggle ? toggle.checked : false;\n  var isStd = selectedPlan === 'standard';\n  var stickerPrice = isStd ? 9.99 : 24.99;\n  var annualPrice  = isStd ? 9.99 : 19.99;\n  var planName     = isStd ? 'Standard' : 'Premium';\n  var stickerLabel = isStd ? 'Standard sticker' : 'Premium 3-sticker bundle';\n\n  // Prepay description\n  var prepayDesc = document.getElementById('prepay-desc');\n  if (prepayDesc) {\n    if (prepayEnabled) {\n      var total = (1 + stickerPrice + annualPrice).toFixed(2);\n      prepayDesc.textContent = 'On: Pay $' + total + ' today. No charges on day 30 or day 60.';\n    } else {\n      prepayDesc.textContent = 'Off: Just $1 today. Sticker + annual billed later.';\n    }\n  }\n\n  // Order summary lines\n  var lines = document.getElementById('summary-lines');\n  if (lines) {\n    var html = '<div style=\"display:flex;justify-content:space-between;padding:8px 0;border-bottom:.5px solid var(--bd)\">' +\n      '<div style=\"font-size:14px;color:var(--bk);font-weight:500\">eTag activation</div>' +\n      '<div style=\"font-size:14px;font-weight:700;color:var(--bk)\">$1.00</div></div>';\n    if (prepayEnabled) {\n      html += '<div style=\"display:flex;justify-content:space-between;padding:8px 0;border-bottom:.5px solid var(--bd)\">' +\n        '<div style=\"font-size:14px;color:var(--bk);font-weight:500\">' + stickerLabel + '</div>' +\n        '<div style=\"font-size:14px;font-weight:700;color:var(--bk)\">$' + stickerPrice.toFixed(2) + '</div></div>' +\n        '<div style=\"display:flex;justify-content:space-between;padding:8px 0\">' +\n        '<div style=\"font-size:14px;color:var(--bk);font-weight:500\">Year 1 ' + planName + ' annual</div>' +\n        '<div style=\"font-size:14px;font-weight:700;color:var(--bk)\">$' + annualPrice.toFixed(2) + '</div></div>';\n    } else {\n      html += '<div style=\"display:flex;justify-content:space-between;padding:8px 0;border-bottom:.5px solid var(--bd)\">' +\n        '<div style=\"font-size:12px;color:var(--gy)\">Day 30: ' + stickerLabel + ' ships</div>' +\n        '<div style=\"font-size:12px;color:var(--gy)\">$' + stickerPrice.toFixed(2) + '</div></div>' +\n        '<div style=\"display:flex;justify-content:space-between;padding:8px 0\">' +\n        '<div style=\"font-size:12px;color:var(--gy)\">Day 60: ' + planName + ' annual begins</div>' +\n        '<div style=\"font-size:12px;color:var(--gy)\">$' + annualPrice.toFixed(2) + '/yr</div></div>';\n    }\n    lines.innerHTML = html;\n  }\n\n  // Consent text\n  var consentDesc = document.getElementById('consent-desc');\n  if (consentDesc) {\n    if (prepayEnabled) {\n      consentDesc.textContent = 'Everything paid today. Your ' + (isStd ? 'Standard sticker' : '3 Premium stickers') + ' will ship in 2-3 business days. Year 1 is fully paid \u2014 no further charges until year 2.';\n    } else {\n      consentDesc.textContent = 'After 30 days, your plan upgrades to ' + planName + ' ($' + stickerPrice.toFixed(2) + ') and we ship a physical NFC + QR sticker' + (isStd ? '' : 's') + ' to your address.';\n    }\n  }\n\n  // Pay button text (only if not mid-processing)\n  var btn = document.getElementById('pay-btn');\n  if (btn && !btn.disabled) {\n    var payAmount = prepayEnabled ? (1 + stickerPrice + annualPrice).toFixed(2) : '1';\n    btn.textContent = 'Pay $' + payAmount + ' \u2014 Activate Tag';\n  }\n}\n\nif (document.readyState === 'loading') {\n  document.addEventListener('DOMContentLoaded', updatePaymentUI);\n} else {\n  updatePaymentUI();\n}\n\nfunction showStep(id) {\n  document.querySelectorAll('.step-view').forEach(v => v.classList.remove('active'));\n  document.getElementById('step-' + id).classList.add('active');\n}\n</script>\n<script>\nif ('serviceWorker' in navigator) {\n  navigator.serviceWorker.register('/sw.js');\n}\n</script>\n\n<div style=\"padding:20px 20px 32px;text-align:center;border-top:.5px solid #E5E7EB;margin-top:24px;background:#fff\">\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0 0 4px\">\n    <a href=\"/privacy.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Privacy</a>\n    &nbsp;\u00b7&nbsp;\n    <a href=\"/terms.html\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Terms</a>\n    &nbsp;\u00b7&nbsp;\n    <a href=\"mailto:support@tapmycar.io\" style=\"color:#FF6B00;text-decoration:none;font-weight:600\">Support</a>\n  </p>\n  <p style=\"font-size:11px;color:#9CA3AF;margin:0\">\u00a9 2026 Praman Tech LLC</p>\n</div>\n\n<script src=\"/tmc-redesign.js\">\n</script>\n\n<script>\n// TMC_PATCH7FIX_SCRIPT_SCOPE\n// Patch 7's new JS was originally inserted into the wrong <script> tag\n// (a <script src=\"...\"> tag, where browsers ignore inline content).\n// This is the same JS, now in a properly-isolated inline script block.\n\n// ===== TMC_PATCH7_ACTIVATE_SMS =====================================================\n// SMS verification UI logic + flow routing.\n//\n// Per-activation SMS gate:\n//  1. After vehicle details, route through phone-verify step\n//  2. pvSendCode() -> POST /api/start-phone-verification\n//  3. SMS arrives, user types code\n//  4. pvVerifyCode() -> POST /api/confirm-phone-verification\n//     -> server returns { success, activation_session_id }\n//  5. session_id stored, control returns to flow handler:\n//     - eTag flow: call activateEtag(session_id)\n//     - Physical upgrade flow: call activatePhysicalSticker(session_id)\n//     - Paid flow: store session_id, proceed to payment step\n//\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nlet pvActivationSessionId = null;\nlet pvAfterVerifyCallback = null;\nlet pvResendTimerId = null;\n\nfunction maskPhone(p) {\n  if (!p) return 'your phone';\n  const digits = String(p).replace(/\\D/g, '');\n  if (digits.length < 4) return 'your phone';\n  return '***-***-' + digits.slice(-4);\n}\n\nfunction pvShow(callback) {\n  pvAfterVerifyCallback = callback;\n  // Reset UI\n  document.getElementById('pv-send-section').style.display = 'flex';\n  document.getElementById('pv-code-section').style.display = 'none';\n  document.getElementById('pv-code-input').value = '';\n  document.getElementById('pv-error').style.display = 'none';\n  document.getElementById('pv-send-btn').disabled = false;\n  document.getElementById('pv-send-btn').textContent = 'Send code via SMS';\n  // Show the user's phone (masked)\n  fetch('/api/get-dashboard?user_id=' + s.token).then(r => r.json()).then(d => {\n    if (d.user && d.user.phone) {\n      document.getElementById('pv-masked-phone').textContent = maskPhone(d.user.phone);\n    }\n  }).catch(() => {});\n  showStep('phone-verify');\n}\n\nasync function pvSendCode() {\n  const btn = document.getElementById('pv-send-btn');\n  btn.disabled = true;\n  btn.textContent = 'Sending...';\n  try {\n    const res = await fetch('/api/start-phone-verification', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({ user_id: s.token })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.success) {\n      btn.disabled = false;\n      btn.textContent = 'Send code via SMS';\n      showToast(data.error || 'Could not send code. Please try again.');\n      return;\n    }\n    // Move to code-entry section\n    document.getElementById('pv-send-section').style.display = 'none';\n    document.getElementById('pv-code-section').style.display = 'flex';\n    document.getElementById('pv-code-input').focus();\n    pvStartResendCooldown();\n  } catch(e) {\n    btn.disabled = false;\n    btn.textContent = 'Send code via SMS';\n    showToast('Network error');\n  }\n}\n\nfunction pvStartResendCooldown() {\n  const btn = document.getElementById('pv-resend-btn');\n  let secs = 60;\n  btn.disabled = true;\n  btn.style.opacity = '.6';\n  btn.textContent = 'Resend code (' + secs + 's)';\n  if (pvResendTimerId) clearInterval(pvResendTimerId);\n  pvResendTimerId = setInterval(() => {\n    secs--;\n    if (secs <= 0) {\n      clearInterval(pvResendTimerId);\n      pvResendTimerId = null;\n      btn.disabled = false;\n      btn.style.opacity = '1';\n      btn.textContent = 'Resend code';\n    } else {\n      btn.textContent = 'Resend code (' + secs + 's)';\n    }\n  }, 1000);\n}\n\nasync function pvResendCode() {\n  const btn = document.getElementById('pv-resend-btn');\n  if (btn.disabled) return;\n  btn.disabled = true;\n  btn.textContent = 'Sending...';\n  try {\n    const res = await fetch('/api/start-phone-verification', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({ user_id: s.token })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.success) {\n      btn.disabled = false;\n      btn.textContent = 'Resend code';\n      showToast(data.error || 'Could not resend');\n      return;\n    }\n    pvStartResendCooldown();\n    showToast('Code resent');\n  } catch(e) {\n    btn.disabled = false;\n    btn.textContent = 'Resend code';\n    showToast('Network error');\n  }\n}\n\nasync function pvVerifyCode() {\n  const code = document.getElementById('pv-code-input').value.trim();\n  const errEl = document.getElementById('pv-error');\n  errEl.style.display = 'none';\n  if (!/^\\d{6}$/.test(code)) {\n    errEl.textContent = 'Please enter the 6-digit code';\n    errEl.style.display = 'block';\n    return;\n  }\n  const btn = document.getElementById('pv-verify-btn');\n  btn.disabled = true;\n  btn.textContent = 'Verifying...';\n  try {\n    const res = await fetch('/api/confirm-phone-verification', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({ user_id: s.token, code })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.success) {\n      btn.disabled = false;\n      btn.textContent = 'Verify and continue';\n      errEl.textContent = data.error || 'Wrong or expired code. Please try again.';\n      errEl.style.display = 'block';\n      return;\n    }\n    if (!data.activation_session_id) {\n      btn.disabled = false;\n      btn.textContent = 'Verify and continue';\n      errEl.textContent = 'Verification succeeded but session creation failed. Please try again.';\n      errEl.style.display = 'block';\n      return;\n    }\n    pvActivationSessionId = data.activation_session_id;\n    btn.textContent = 'Continuing...';\n    if (pvAfterVerifyCallback) pvAfterVerifyCallback(pvActivationSessionId);\n  } catch(e) {\n    btn.disabled = false;\n    btn.textContent = 'Verify and continue';\n    errEl.textContent = 'Network error. Please try again.';\n    errEl.style.display = 'block';\n  }\n}\n\n// ===== TMC_PATCH7_ACTIVATE_SMS flow routing =========================================\n// Decides which activation path to take based on what kind of tag is being\n// activated. Called from proceedToPayment() and proceedFromCarChoice().\n\nfunction flowAfterVehicle() {\n  // Determine what kind of activation this is.\n  // - scannedTag.owner_id === s.token AND status === 'claimed' AND token starts with TMC-ET\n  //   -> own claimed eTag, free activation\n  // - isPhysicalUpgrade === true AND user is on paid plan -> free physical upgrade\n  // - else -> paid new physical (Stripe checkout)\n  //\n  // In all cases: SMS verify first, then route to activation.\n\n  const isOwnEtag = scannedTag &&\n    scannedTag.owner_id === s.token &&\n    (scannedTag.status === 'claimed' || scannedTag.status === 'unclaimed') &&\n    (scannedTag.token || '').toUpperCase().indexOf('TMC-ET') === 0;\n\n  if (isOwnEtag) {\n    // Free eTag activation: SMS verify, then activateEtag with session_id\n    pvShow((sessionId) => activateEtag(sessionId));\n    return;\n  }\n\n  if (isPhysicalUpgrade) {\n    // Free physical upgrade for paid user: SMS verify, then activatePhysicalSticker\n    pvShow((sessionId) => activatePhysicalSticker(sessionId));\n    return;\n  }\n\n  /* TMC_PATCH35C1_GIFT_CLAIM: gift tag \u2014 SMS verify, then claim with NO payment */\n  if (scannedTag && scannedTag.is_gift === true) {\n    pvShow((sessionId) => activateGiftTag(sessionId));\n    return;\n  }\n\n  // Paid new physical: SMS verify first, then go to payment step.\n  // The session_id is stored in pvActivationSessionId and consumed by\n  // create-checkout (via Stripe metadata) and the webhook.\n  pvShow((sessionId) => {\n    // Store in localStorage as backup so it survives the Stripe round-trip\n    try { localStorage.setItem('tmc_pending_activation_session', sessionId); } catch(e) {}\n    showStep('payment');\n  });\n}\n\n// TMC_PATCH35C1_GIFT_CLAIM: gift tag activation. Claims the tag with no payment. The\n// backend (get-tag.js) detects is_gift and applies the trial plan + expiry\n// to the user automatically.\nasync function activateGiftTag(activationSessionId) {\n  try {\n    const res = await fetch('/api/get-tag', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        token: scannedToken,\n        user_id: s.token,\n        activation_session_id: activationSessionId,\n        license_plate: vehicleData.license_plate,\n        car_make: vehicleData.car_make,\n        car_model: vehicleData.car_model,\n        car_year: vehicleData.car_year,\n        car_color: vehicleData.car_color\n      })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.success) {\n      showToast(data.error || 'Activation failed. Please try again.');\n      showStep('vehicle');\n      return;\n    }\n    let planName = 'your plan';\n    let monthsTxt = '';\n    if (data.gift) {\n      planName = (data.gift.plan || 'standard');\n      planName = planName.charAt(0).toUpperCase() + planName.slice(1);\n      monthsTxt = (data.gift.months || 1) + '-month';\n    }\n    document.getElementById('success-title').textContent = 'Gift Activated! \\uD83C\\uDF81';\n    document.getElementById('success-message').textContent =\n      'Your free ' + monthsTxt + ' ' + planName + ' trial is active and your sticker is ready. Place it on your vehicle and you are all set.';\n    showStep('success');\n  } catch(e) {\n    showToast('Network error. Please try again.');\n    showStep('vehicle');\n  }\n}\n\n// ===== TMC_PATCH7_ACTIVATE_SMS activateEtag =========================================\n// Free eTag activation. Parallel to activatePhysicalSticker but no payment,\n// no eTag deactivation, just claim + activate the user's own eTag.\n\nasync function activateEtag(activationSessionId) {\n  try {\n    const res = await fetch('/api/get-tag', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        token: scannedToken,\n        user_id: s.token,\n        activation_session_id: activationSessionId,\n        license_plate: vehicleData.license_plate,\n        car_make: vehicleData.car_make,\n        car_model: vehicleData.car_model,\n        car_year: vehicleData.car_year,\n        car_color: vehicleData.car_color\n      })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.success) {\n      showToast(data.error || 'Activation failed. Please try again.');\n      // Stay on phone-verify step so user can retry (with new SMS)\n      showStep('vehicle');\n      return;\n    }\n    document.getElementById('success-title').textContent = 'eTag Activated!';\n    document.getElementById('success-message').textContent = 'Your eTag is now active. Print or download it from the Free eTag page to use on your vehicle.';\n    showStep('success');\n  } catch(e) {\n    showToast('Network error. Please try again.');\n    showStep('vehicle');\n  }\n}\n\n// ===== TMC_PATCH7_ACTIVATE_SMS URL ?token= reading =================================\n// If activate.html is loaded with ?token=TMC-XXXXX in the URL, auto-process\n// that token as if it had been scanned. Lets etag.html link directly to\n// activate.html without forcing the user through the QR scanner.\n(function tmcReadUrlToken() {\n  try {\n    const params = new URLSearchParams(window.location.search);\n    const t = params.get('token');\n    if (!t) return;\n    const cleaned = t.toUpperCase().replace(/[^A-Z0-9-]/g, '');\n    if (!cleaned) return;\n    // Wait briefly so the page is initialized, then process\n    setTimeout(() => {\n      try { stopScanner(); } catch(e) {}\n      processToken(cleaned);\n    }, 300);\n  } catch(e) { /* noop */ }\n})();\n\n/* TMC_ACTIVATE_HONEST: small visible error banner so activation failures stop being silent. */\nfunction tmcShowActivationError(msg) {\n  try {\n    var existing = document.getElementById('tmc-activation-error');\n    if (existing) existing.remove();\n    var div = document.createElement('div');\n    div.id = 'tmc-activation-error';\n    div.style.cssText = 'position:fixed;left:12px;right:12px;bottom:12px;background:#7F1D1D;color:#fff;padding:14px 16px;border-radius:12px;font-size:13px;line-height:1.45;box-shadow:0 12px 32px rgba(0,0,0,.3);z-index:99999;font-family:inherit';\n    div.innerHTML = '<div style=\"font-weight:800;margin-bottom:4px\">Activation failed</div><div style=\"opacity:.92\">' + String(msg || 'Unknown error').replace(/</g,'&lt;') + '</div><div style=\"margin-top:8px;font-size:11px;opacity:.7\">Tap this message to dismiss.</div>';\n    div.onclick = function () { div.remove(); };\n    document.body.appendChild(div);\n    setTimeout(function () { try { div.remove(); } catch(_) {} }, 14000);\n  } catch (_) { alert('Activation failed: ' + msg); }\n}\n</script>\n</body>\n</html>";
